import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { transaction } from './db.ts';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** Public job representation returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** Raw row in the `jobs` table. Internal columns (seq, available_at, idempotency_key) never leave the server. */
export interface JobRow {
  seq: number;
  id: string;
  idempotency_key: string | null;
  input: string;
  steps: number;
  fail_attempts: number;
  status: JobStatus;
  attempts: number;
  completed_steps: number;
  output: string | null;
  error: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

export interface FieldError {
  field: string;
  message: string;
}

export interface JobPayload {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ParseResult =
  | { ok: true; payload: JobPayload; idempotencyKey: string | null }
  | { ok: false; fields: FieldError[] };

const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

/**
 * Validates a submission and applies defaults. Collects every identifiable error rather than stopping at the first.
 * Pure: performs no database access.
 */
export function parseCreateRequest(
  contentType: string | undefined,
  rawBody: string,
  idempotencyHeader: string | undefined,
): ParseResult {
  const fields: FieldError[] = [];
  let idempotencyKey: string | null = null;

  if (idempotencyHeader !== undefined) {
    if (IDEMPOTENCY_KEY_RE.test(idempotencyHeader)) idempotencyKey = idempotencyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return { ok: false, fields };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    fields.push({ field: 'body', message: 'body must be valid JSON' });
    return { ok: false, fields };
  }
  if (!isPlainObject(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return { ok: false, fields };
  }

  for (const key of Object.keys(parsed)) {
    if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  if (!Object.hasOwn(parsed, 'input')) {
    fields.push({ field: 'input', message: 'is required' });
  } else {
    const value = parsed.input;
    if (typeof value !== 'string') {
      fields.push({ field: 'input', message: 'must be a string' });
    } else if (value.length < 1 || value.length > 1000) {
      fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
    } else if (value.trim() === '') {
      fields.push({ field: 'input', message: 'must not be only whitespace' });
    } else {
      input = value;
    }
  }

  const steps = readInteger(parsed, 'steps', 1, 20, 5, fields);
  const failAttempts = readInteger(parsed, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, payload: { input, steps: steps!, failAttempts: failAttempts! }, idempotencyKey };
}

function readInteger(
  body: Record<string, unknown>,
  name: string,
  min: number,
  max: number,
  defaultValue: number,
  fields: FieldError[],
): number | undefined {
  if (!Object.hasOwn(body, name)) return defaultValue;
  const value = body[name];
  if (typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max) return value;
  fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
  return undefined;
}

/** Converts a row to the public representation. Every field is always present. */
export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed_steps, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function getRow(db: DatabaseSync, sql: string, ...params: (string | number)[]): JobRow | undefined {
  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
}

export type CreateResult =
  | { kind: 'created'; job: Job }
  | { kind: 'replayed'; job: Job }
  | { kind: 'conflict' };

/**
 * Creates a job, or replays/rejects an idempotency key. The lookup and insert share one immediate transaction,
 * and the UNIQUE constraint on idempotency_key is the database-level guarantee.
 */
export function createJob(db: DatabaseSync, payload: JobPayload, idempotencyKey: string | null): CreateResult {
  return transaction(db, (): CreateResult => {
    if (idempotencyKey !== null) {
      const existing = getRow(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', idempotencyKey);
      if (existing) {
        const same =
          existing.input === payload.input &&
          existing.steps === payload.steps &&
          existing.fail_attempts === payload.failAttempts;
        return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
      }
    }
    const now = new Date().toISOString();
    const id = randomUUID();
    db.prepare(
      `INSERT INTO jobs (id, idempotency_key, input, steps, fail_attempts, status, attempts, completed_steps,
                         output, error, available_at, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, 'queued', 0, 0, NULL, NULL, 0, ?, ?)`,
    ).run(id, idempotencyKey, payload.input, payload.steps, payload.failAttempts, now, now);
    const row = getRow(db, 'SELECT * FROM jobs WHERE id = ?', id)!;
    return { kind: 'created', job: toJob(row) };
  });
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = getRow(db, 'SELECT * FROM jobs WHERE id = ?', id);
  return row ? toJob(row) : undefined;
}

/** All jobs, newest first (by insertion sequence). */
export function listJobs(db: DatabaseSync): Job[] {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  return rows.map(toJob);
}

// ---- Worker heartbeat -------------------------------------------------------------------------

export const HEARTBEAT_STALE_MS = 3000;

export function writeHeartbeat(db: DatabaseSync, now: number = Date.now()): void {
  db.prepare(
    `INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?)
     ON CONFLICT (id) DO UPDATE SET beat_at = excluded.beat_at`,
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.exec('DELETE FROM worker_heartbeat');
}

export function isWorkerUp(db: DatabaseSync, now: number = Date.now()): boolean {
  const row = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as
    | { beat_at: number }
    | undefined;
  return row !== undefined && now - row.beat_at <= HEARTBEAT_STALE_MS;
}

// ---- Worker processing ------------------------------------------------------------------------

/**
 * Picks the next job to work on, in one short transaction.
 * - A job left `running` (its worker died) is resumed first without counting a new attempt, and its progress restarts at 0.
 * - Otherwise the oldest queued job whose retry delay has passed is claimed and its attempt count incremented.
 */
export function claimNextJob(db: DatabaseSync, now: number = Date.now()): JobRow | undefined {
  return transaction(db, (): JobRow | undefined => {
    const stamp = new Date(now).toISOString();
    const interrupted = getRow(db, "SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1");
    if (interrupted) {
      db.prepare(
        'UPDATE jobs SET completed_steps = 0, output = NULL, error = NULL, updated_at = ? WHERE seq = ?',
      ).run(stamp, interrupted.seq);
      return { ...interrupted, completed_steps: 0, output: null, error: null };
    }
    const next = getRow(
      db,
      "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1",
      now,
    );
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0,
                       output = NULL, error = NULL, updated_at = ? WHERE seq = ?`,
    ).run(stamp, next.seq);
    return { ...next, status: 'running', attempts: next.attempts + 1, completed_steps: 0, output: null, error: null };
  });
}

export function recordProgress(db: DatabaseSync, seq: number, completedSteps: number): void {
  db.prepare(`UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE seq = ? AND status = 'running'`).run(
    completedSteps,
    new Date().toISOString(),
    seq,
  );
}

export function completeJob(db: DatabaseSync, seq: number, output: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', completed_steps = steps, output = ?, error = NULL, updated_at = ?
     WHERE seq = ? AND status = 'running'`,
  ).run(output, new Date().toISOString(), seq);
}

export function requeueForRetry(db: DatabaseSync, seq: number, availableAt: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed_steps = 0, output = NULL, error = NULL,
                     available_at = ?, updated_at = ?
     WHERE seq = ? AND status = 'running'`,
  ).run(availableAt, new Date().toISOString(), seq);
}

export function failJob(db: DatabaseSync, seq: number, error: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', completed_steps = 0, output = NULL, error = ?, updated_at = ?
