import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import {
  createJob,
  getJob,
  isWorkerUp,
  listJobs,
  parseCreateRequest,
  type FieldError,
} from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** Requests larger than this are rejected as an invalid body; the longest valid submission is far smaller. */
const MAX_BODY_BYTES = 64 * 1024;

function sendJson(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  const text = JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(text),
    ...extraHeaders,
  });
  res.end(text);
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  extraHeaders: Record<string, string> = {},
): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error }, extraHeaders);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  if (tooLarge) {
    sendError(res, 400, 'invalid_request', 'Request validation failed.', [
      { field: 'body', message: 'request body is too large' },
    ]);
    return;
  }
  const parsed = parseCreateRequest(req.headers['content-type'], text, req.headers['idempotency-key']);
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'Request validation failed.', parsed.fields);
    return;
  }
  const outcome = createJob(db, parsed.payload, parsed.idempotencyKey);
  switch (outcome.kind) {
    case 'created':
      sendJson(res, 201, outcome.job);
      return;
    case 'replayed':
      sendJson(res, 200, outcome.job);
      return;
    case 'conflict':
      sendError(
        res,
        409,
        'idempotency_conflict',
        'Idempotency-Key was already used with a different payload.',
      );
      return;
  }
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.', undefined, {
    allow: allowed.join(', '),
  });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  // Route on the raw path: no URL normalization, so `//` or `..` cannot reroute a request.
  const path = (req.url ?? '/').split('?')[0]!;
  const method = req.method ?? 'GET';
  const isRead = method === 'GET' || method === 'HEAD';

  if (path === '/') {
    if (!isRead) return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'content-length': Buffer.byteLength(uiHtml) });
    res.end(method === 'HEAD' ? undefined : uiHtml);
    return;
  }

  if (path === '/health') {
    if (!isRead) return methodNotAllowed(res, ['GET']);
    sendJson(res, 200, { status: 'ok', worker: isWorkerUp(db) ? 'up' : 'down' });
    return;
  }

  if (path === '/api/jobs') {
    if (isRead) {
      sendJson(res, 200, { jobs: listJobs(db) });
      return;
    }
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const item = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (item) {
    if (!isRead) return methodNotAllowed(res, ['GET']);
    const job = getJob(db, item[1]!);
    if (!job) sendError(res, 404, 'not_found', 'No job with that id.');
    else sendJson(res, 200, job);
    return;
  }

  sendError(res, 404, 'not_found', 'Not found.');
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err instanceof Error ? err.message : err);
    if (res.headersSent) {
      res.end();
    } else {
      sendError(res, 500, 'internal_error', 'Unexpected server error.');
    }
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  // Stop accepting connections and let in-flight requests finish. Idle keep-alive sockets are closed by close().
  server.close(() => {
    db.close();
    console.log('server stopped');
  });
  // Bound the drain so a stalled client cannot block exit.
  setTimeout(() => server.closeAllConnections(), 2000).unref();
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

