import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  recordProgress,
  requeueForRetry,
  writeHeartbeat,
  type JobRow,
} from './jobs.ts';
import type { DatabaseSync } from 'node:sqlite';

/** Simulated duration of one processing step. */
const STEP_MS = 100;
/** Delay before a transiently failed attempt is retried. Must be within 250 ms to 2 s. */
const RETRY_DELAY_MS = 500;
/** Total attempts allowed, including the first. */
const MAX_ATTEMPTS = 3;
const HEARTBEAT_INTERVAL_MS = 500;
const IDLE_POLL_MS = 100;

let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/**
 * Runs one attempt of a job. Returns early without writing anything else when shutting down, leaving the job
 * `running` so the next worker start resumes it.
 */
async function runAttempt(db: DatabaseSync, job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress is recorded.
    await sleep(STEP_MS);
    if (stopping) return;
    if (job.attempts < MAX_ATTEMPTS) {
      requeueForRetry(db, job.seq, Date.now() + RETRY_DELAY_MS);
    } else {
      failJob(db, job.seq, 'transient failure');
    }
    return;
  }

  for (let completed = 1; completed <= job.steps; completed++) {
    await sleep(STEP_MS);
    if (stopping) return;
    if (completed < job.steps) {
      recordProgress(db, job.seq, completed);
    } else {
      completeJob(db, job.seq, job.input.toUpperCase());
    }
  }
}

async function main(): Promise<void> {
  const db = openDatabase();
  writeHeartbeat(db);
  const heartbeat = setInterval(() => {
    try {
      writeHeartbeat(db);
    } catch (err) {
      console.error('heartbeat failed:', err instanceof Error ? err.message : err);
    }
  }, HEARTBEAT_INTERVAL_MS);

  console.log('worker started');
  while (!stopping) {
    try {
      const job = claimNextJob(db, Date.now());
      if (!job) {
        await sleep(IDLE_POLL_MS);
        continue;
      }
      await runAttempt(db, job);
    } catch (err) {
      console.error('worker error:', err instanceof Error ? err.message : err);
      await sleep(1000);
    }
  }

  clearInterval(heartbeat);
  clearHeartbeat(db);
  db.close();
  console.log('worker stopped');
}

await main();

